mapper.sql:
dismissal.user_id = #{userId}
AND dismissal.order_kind = '${documentKind}'
AND dismissal.document_id = document.id

mapper.select:
SELECT id, kind, order_no, model_name, order_qty, shipped_qty, status FROM (
SELECT document.id, 'ORDER' kind, document.order_no, COALESCE( (SELECT GROUP_CONCAT(DISTINCT m.model_name ORDER BY m.model_name SEPARATOR '、') FROM bike_order_reservation_item ri JOIN bike_production_sku sku ON sku.id = ri.sku_id JOIN bike_product_model m ON m.id = sku.model_id WHERE ri.order_id = document.id), (SELECT GROUP_CONCAT(DISTINCT m.model_name ORDER BY m.model_name SEPARATOR '、') FROM bike_sales_order_item oi JOIN bike_product_model m ON m.id = oi.product_model_id WHERE oi.order_id = document.id) ) model_name, (SELECT COALESCE(SUM(oi.ordered_qty), 0) FROM bike_sales_order_item oi WHERE oi.order_id = document.id) order_qty, (SELECT COALESCE(SUM(oi.shipped_qty), 0) FROM bike_sales_order_item oi WHERE oi.order_id = document.id) shipped_qty, CASE WHEN document.status IN ('DRAFT', 'PENDING') AND pi.status IN ('CONFIRMED', 'RELEASED') THEN pi.status ELSE document.status END status, document.created_at FROM bike_sales_order document LEFT JOIN bike_pi_order_link ol ON ol.order_id = document.id LEFT JOIN bike_pi_series series ON series.id = ol.series_id LEFT JOIN bike_pi pi ON pi.id = series.current_pi_id AND pi.customer_id = document.customer_id AND (document.agent_id IS NULL OR pi.agent_id = document.agent_id) WHERE 1 = 1
UNION ALL
SELECT series.id, 'PI' kind, series.pi_no order_no, (SELECT GROUP_CONCAT(DISTINCT item.model_name ORDER BY item.model_name SEPARATOR '、') FROM bike_pi_item item WHERE item.pi_id = document.id) model_name, (SELECT COALESCE(SUM(item.ordered_qty), 0) FROM bike_pi_item item WHERE item.pi_id = document.id) order_qty, 0 shipped_qty, document.status, series.created_at FROM bike_pi_series series JOIN bike_pi document ON document.id = series.current_pi_id WHERE 1 = 1
AND series.id = #{id}
) visible_orders ORDER BY created_at DESC, id DESC, kind LIMIT #{offset}, 20

SELECT
    (SELECT COUNT(*) FROM bike_sales_order document WHERE 1 = 1 
        )
    + (SELECT COUNT(*) FROM bike_pi_series series JOIN bike_pi document ON document.id = series.current_pi_id
        WHERE 1 = 1 
        )

SELECT EXISTS (
    SELECT 1 
    AND EXISTS (
        SELECT 1 FROM bike_customer_order_dismissal dismissal
        WHERE dismissal.user_id = #{userId} AND dismissal.order_kind = #{kind}
          AND dismissal.document_id = document.id
    )
)
